<script setup>
import TrendChart from './TrendChart.vue'
import CctvViewer from './CctvViewer.vue'
import EquipmentTable from './EquipmentTable.vue'
import { calculateKpi } from '../kpi'
defineProps({ widget: Object, blocks: Array, assets: Array, data: Object, dark: Boolean, blockId: String })
const format = value => value === null ? 'Unavailable' : new Intl.NumberFormat('en-SG', { maximumFractionDigits: 1 }).format(value)
</script>
<template>
  <template v-if="widget.type === 'kpi'"><div class="kpi-top"><span class="widget-icon" :class="widget.color"><i aria-hidden="true" :class="`fa-solid fa-${widget.icon}`"></i></span><span class="reading-tag">{{ widget.periodLabel || 'TODAY' }}</span></div><h3 :title="widget.title">{{ widget.title }}</h3><div class="kpi-value">{{ format(calculateKpi(widget, blocks, data.trends)) }} <span>{{ widget.unit }}</span></div><p class="kpi-detail" :title="widget.detail"><span class="tiny-dot" :class="widget.color"></span>{{ widget.detail }}</p></template>
  <template v-else><div class="card-heading"><h3>{{ widget.title }}</h3><span class="tag">{{ widget.type === 'footage' ? 'Local demo clips' : widget.type === 'table' ? 'Location summary' : widget.type === 'equipment' ? 'Demo inventory' : 'Consumption' }}</span></div><CctvViewer v-if="widget.type === 'footage'" :cameras="data.cameras" :assets="data.assets" :block-id="blockId"/><TrendChart v-else-if="['line', 'bar'].includes(widget.type)" :widget="widget" :blocks="blocks" :trends="data.trends" :dark="dark"/><div v-else-if="widget.type === 'water-table'" class="table-scroll"><p class="range-availability">Current demo readings; consumption is day-to-date.</p><table><thead><tr><th>Location</th><th>Water (m³)</th><th>Pressure (bar)</th><th>Tank fill (%)</th><th>Meters online</th><th>Open alerts</th></tr></thead><tbody><tr v-for="b in blocks" :key="b.id"><td>{{ b.name }}</td><td>{{ format(b.waterM3) }}</td><td>{{ format(b.waterPressureBar) }}</td><td>{{ b.tankLevelPercent }}</td><td :class="b.waterMetersOnline &lt; b.waterMetersTotal ? 'warning-text' : 'good-text'">{{ b.waterMetersOnline }}/{{ b.waterMetersTotal }}</td><td :class="b.waterAlerts ? 'warning-text' : 'good-text'">{{ b.waterAlerts }}</td></tr></tbody></table><p v-for="alert in (data.waterAlerts || []).filter(a => blocks.some(b => b.id === a.blockId))" :key="alert.id" class="range-availability"><strong>{{ alert.title }}:</strong> {{ alert.detail }}</p></div><EquipmentTable v-else-if="widget.type === 'equipment'" :category="widget.category" :assets="assets" :blocks="data.blocks"/><div v-else class="table-scroll"><table><thead><tr><th>Location</th><th>Energy</th><th>Water</th><th>Temperature</th><th>Cameras</th></tr></thead><tbody><tr v-for="b in blocks" :key="b.id"><td><span class="block-badge"><i aria-hidden="true" class="fa-solid fa-building"></i></span>{{ b.name }}</td><td>{{ format(b.energyKwh) }} <small>kWh</small></td><td>{{ format(b.waterM3) }} <small>m³</small></td><td>{{ format(b.temperatureC) }} <small>°C</small></td><td><span :class="b.camerasOnline < b.camerasTotal ? 'warning-text' : 'good-text'">{{ b.camerasOnline }}/{{ b.camerasTotal }} online</span></td></tr></tbody></table></div></template>
</template>
